import __builtin__, os, sys
script = os.path.abspath('bin/read-documents.py')
real_open = __builtin__.open
state = {'calls': 0, 'active': 0, 'max_active': 0, 'closed': 0}
class TrackedFile(object):
    def __init__(self, wrapped):
        self.wrapped = wrapped
    def __enter__(self):
        return self
    def __exit__(self, exc_type, exc_value, traceback):
        self.close()
        return False
    def read(self, *args, **kwargs):
        return self.wrapped.read(*args, **kwargs)
    def close(self):
        if not self.wrapped.closed:
            self.wrapped.close()
            state['active'] -= 1
            state['closed'] += 1

def tracked_open(path, *args, **kwargs):
    state['calls'] += 1
    if state['calls'] == 250:
        raise IOError('injected open failure')
    wrapped = real_open(path, *args, **kwargs)
    state['active'] += 1
    state['max_active'] = max(state['max_active'], state['active'])
    return TrackedFile(wrapped)

saved_stdout = sys.stdout
sink = real_open(os.devnull, 'w')
sys.stdout = sink
__builtin__.open = tracked_open
sys.argv = [script, '500']
failed = False
try:
    execfile(script, {'__file__': script, '__name__': '__main__'})
except IOError as exc:
    failed = str(exc) == 'injected open failure'
finally:
    __builtin__.open = real_open
    sys.stdout = saved_stdout
    sink.close()
print 'INJECTED_FAILURE_CAUGHT=%s OPEN_CALLS=%d PRIOR_HANDLES_CLOSED=%d ACTIVE_HANDLES_AFTER_FAILURE=%d MAX_ACTIVE_HANDLES=%d' % (
    failed, state['calls'], state['closed'], state['active'], state['max_active'])
if not failed or state['calls'] != 250 or state['closed'] != 249 or state['active'] != 0 or state['max_active'] != 1:
